# Large-range sweep of the O(l*d) composition method (scripts/frontier/pattern/l859_compose.py), rewritten
# for memory/speed so it scales to l ~ 5000+:
#   * basis f_i = Delta^i E4^{a_i} E6^b of S_{l-1}, generated by the recurrence
#       f_i = q^i * G * h^{d-i},  G = E6^b E4^{a_d} Delta'^d,  h = E4^3 / Delta',  Delta' = Delta/q,
#     (a_i = a_d + 3(d-i), b constant since k - 12i == k mod 12), one truncated product per basis element;
#   * only the needed coefficients of each f_i (and of P*f_i) are kept, so memory is O(L) not O(dL);
#   * mul_low / pow_trunc / inverse_series_trunc from python-flint >= 0.7.
# Mathematics identical to l859_compose.py (same basis, same truncation argument, same tests):
#   Ubar: coeff_n = a_{ln};  Dbar f: coeff_n = coeff_{ln-delta}(P f), P = 1/eta-series = sum p(n) q^n.
# Per prime: Theorem A (det X|V != 0, rank = R), d_l = 0 via rank[X^d | D_M] = rank X^d, rank X^2 = rank X,
# Krylov rank of Lbar(1) = Dbar(1) under X|V, charpoly(X|V) factorization; for Krylov < R a full
# obstruction analysis (geometric multiplicities, cyclicity of X|V, local minimal polynomial of Lbar(1)).
# Usage: python sweep.py LO HI OUT.jsonl     (skips primes already present in OUT)
import sys, time, json, os
import numpy as np, sympy
from flint import nmod_poly, nmod_mat

def dimS(k):
    if k < 12 or k % 2: return 0
    return k // 12 - (1 if k % 12 == 2 else 0)

def eis46(L, p):
    s3 = np.zeros(L, dtype=np.int64); s5 = np.zeros(L, dtype=np.int64)
    for d in range(1, L):
        s3[d::d] += pow(d, 3, p); s5[d::d] += pow(d, 5, p)
    s3 %= p; s5 %= p
    e4 = (240 * s3) % p; e4[0] = 1
    e6 = (-504 * s5) % p; e6[0] = 1
    return nmod_poly([int(x) for x in e4], p), nmod_poly([int(x) for x in e6], p)

def pent(L, p):
    e = [0] * L; k = 0
    while True:
        done = True
        for kk in ((k, -k) if k else (0,)):
            x = kk * (3 * kk - 1) // 2
            if x < L: e[x] += (1 if kk % 2 == 0 else -1); done = False
        if done and k > 0: break
        k += 1
    return nmod_poly([x % p for x in e], p)

def M(rows, p):  # list of rows -> nmod_mat
    return nmod_mat(len(rows), len(rows[0]), [x % p for r in rows for x in r], p)

def ident(n, p): return M([[1 if i == j else 0 for j in range(n)] for i in range(n)], p)

def polymat(f, A, n, p):  # f(A) by Horner
    cs = [int(c) for c in f.coeffs()]; R = M([[0] * n for _ in range(n)], p); I = ident(n, p)
    for c in reversed(cs): R = R * A + I * c
    return R

def mpow(A, e, n, p):
    R = ident(n, p); B = A
    while e:
        if e & 1: R = R * B
        e >>= 1
        if e: B = B * B
    return R

def fstr(fa):
    return ' * '.join(f'({f})^{e}' if e > 1 else f'({f})' for f, e in fa)

def analyze(l, EXTRA=12):
    p = l; T0 = time.time()
    j = l % 24; t = (l - j) // 24; rho = (j * l - 1) // 24; kp = (l + j - 2) // 2
    delta = (l * l - 1) // 24; k = l - 1; d = dimS(k); R = (l + 12) // 24; r = dimS(kp)
    EXTRA = min(EXTRA, l - 1 - d); NC = d + EXTRA; L = l * NC + 1
    assert L < l * l and EXTRA >= 4
    eta = pent(L, p); P = eta.inverse_series_trunc(L)
    Dp = eta.pow_trunc(24, L)                                       # Delta' = Delta / q
    E4, E6 = eis46(L, p)
    tser = time.time() - T0
    def ab(w):
        for bb in range(3):
            if w - 6 * bb >= 0 and (w - 6 * bb) % 4 == 0: return (w - 6 * bb) // 4, bb
        raise ValueError
    recipe = [ab(k - 12 * i) for i in range(1, d + 1)]
    b = recipe[0][1]; ad = recipe[-1][0]
    assert all(recipe[i - 1] == (ad + 3 * (d - i), b) for i in range(1, d + 1))
    recipe_kp = [ab(kp - 12 * i) for i in range(1, r + 1)]
    V_is_tail = (r == d - t) and all(recipe_kp[i - 1] == recipe[t + i - 1] for i in range(1, r + 1))
    G = E4.pow_trunc(ad, L).mul_low(Dp.pow_trunc(d, L), L)
    if b: G = G.mul_low(E6.pow_trunc(b, L), L)
    h = E4.pow_trunc(3, L).mul_low(Dp.inverse_series_trunc(L), L)
    PG = P.mul_low(G, L)
    # H = G h^m, J = P G h^m; f_i = q^i H (m = d-i), so coeff_n(f_i) = H[n-i], coeff_n(P f_i) = J[n-i]
    low = [None] * d; Uc = [None] * d; Dc = [None] * d
    H, J = G, PG
    for m in range(d):
        i = d - m
        low[i - 1] = [int(H[n - i]) if n >= i else 0 for n in range(1, NC + 1)]
        Uc[i - 1] = [int(H[l * n - i]) for n in range(1, NC + 1)]
        Dc[i - 1] = [int(J[l * n - delta - i]) if l * n - delta - i >= 0 else 0 for n in range(1, NC + 1)]
        if m < d - 1: H = H.mul_low(h, L); J = J.mul_low(h, L)
    D1 = [int(P[l * n - delta]) if l * n - delta >= 0 else 0 for n in range(1, NC + 1)]   # Dbar(1)
    tbas = time.time() - T0 - tser
    # unitriangular check: f_i = q^i + O(q^{i+1})
    tri = all(low[i][n] % p == (1 if n == i else 0) for i in range(d) for n in range(i + 1))
    Bfull = M([[low[i][n] for i in range(d)] for n in range(NC)], p)   # NC x d
    B = M([[low[i][n] for i in range(d)] for n in range(d)], p); Binv = B.inv()
    def coords(cols):
        C = M([[cols[c][n] for c in range(len(cols))] for n in range(d)], p)
        X = Binv * C
        Cfull = M([[cols[c][n] for c in range(len(cols))] for n in range(NC)], p)
        return X, (Bfull * X).entries() == Cfull.entries()
    Um, okU = coords(Uc)
    Dm, okD = coords([D1] + Dc)                                    # d x (d+1), col 0 = Dbar(1)
    lowzero = all(col[n] % p == 0 for col in [D1] + Dc for n in range(t))
    Dl = Dm.tolist()
    DS = M([[int(Dl[a][c + 1]) for c in range(d)] for a in range(d)], p)
    X = DS * Um
    Xl = [[int(x) for x in row] for row in X.tolist()]
    rkX = X.rank(); rkDS = DS.rank(); rkDM = Dm.rank(); rkU = Um.rank()
    XS_in_V = all(Xl[a][c] == 0 for a in range(t) for c in range(d))
    Xi = M([[Xl[t + a][t + c] for c in range(d - t)] for a in range(d - t)], p)
    n = d - t
    detXi = int(Xi.det()); rkXi = Xi.rank()
    rkX2 = (X * X).rank()
    Xd = mpow(X, d, d, p); rkXd = Xd.rank()
    Xdl = [[int(x) for x in row] for row in Xd.tolist()]
    aug = M([Xdl[a] + [int(x) for x in Dl[a]] for a in range(d)], p)
    rk_aug = aug.rank()
    # Krylov of v = Dbar(1) in V
    vfull = [int(Dl[a][0]) for a in range(d)]
    v_in_V = all(vfull[a] == 0 for a in range(t))
    v = M([[vfull[t + a]] for a in range(n)], p)
    K = []; cur = v
    for _ in range(n + 1):
        K.append([int(x) for x in cur.entries()]); cur = Xi * cur
    kry = M(K, p).rank()
    cp = Xi.charpoly(); fa = cp.factor()[1]
    sqfree = all(e == 1 for _, e in fa)
    rep = []
    for f, e in fa:
        if e > 1:
            kd = n - polymat(f, Xi, n, p).rank()
            rep.append(dict(f=str(f), e=e, deg=f.degree(), geo=kd // f.degree()))
    res = dict(l=l, j=j, d=d, R=R, r=r, t=t, NC=NC, L=L, tri=tri, V_is_tail=V_is_tail, okU=okU, okD=okD,
               lowzero=lowzero, XS_in_V=XS_in_V, v_in_V=v_in_V, rkU=rkU, rkD_S=rkDS, rkD_M=rkDM, rkX=rkX,
               rkX2=rkX2, rkXd=rkXd, rk_aug=rk_aug, rkXi=rkXi, detXi=detXi,
               thmA=(detXi != 0 and rkXi == R and n == R), d_l_zero=(rk_aug == rkXd), ss0=(rkX2 == rkX),
               krylov=kry, sqfree=sqfree, fdegs=sorted([f.degree() for f, e in fa for _ in range(e)]),
               repeated=rep, charpolyXi=fstr(fa) if (R <= 40 or kry < R or not sqfree) else None)
    if kry < R:
        mp = Xi.minpoly()
        cyc_op = (mp == cp)
        # local minimal polynomial of v: dependency among v, Xv, ..., X^kry v
        Kt = M([[K[c][a] for c in range(kry + 1)] for a in range(n)], p)
        ns, nul = Kt.nullspace()
        cvec = [int(ns[i, 0]) for i in range(kry + 1)]
        inv = pow(cvec[kry], -1, p); mv = nmod_poly([c * inv % p for c in cvec], p)
        prim = []
        for f, e in fa:
            ev = 0; g = mv
            while g.degree() >= f.degree() and (g % f).is_zero(): g = g // f; ev += 1
            em = 0; g = mp
            while g.degree() >= f.degree() and (g % f).is_zero(): g = g // f; em += 1
            kd = n - polymat(f, Xi, n, p).rank()
            prim.append(dict(f=str(f), e_charpoly=e, e_minpoly=em, e_minpoly_v=ev, geo=kd // f.degree(),
                             deficit=f.degree() * (e - ev)))
        if any(x['geo'] >= 2 for x in prim):
            obst = 'geometric multiplicity >= 2 (X|V not cyclic; no vector cyclic)'
        elif cyc_op:
            obst = 'X|V cyclic; Lbar(1) misses part of primary component(s): ' + \
                   ', '.join(f"{x['f']}^{x['e_charpoly']} (v-exp {x['e_minpoly_v']})" for x in prim if x['e_minpoly_v'] < x['e_charpoly'])
        else:
            obst = 'other'
        res['exception'] = dict(minpoly_eq_charpoly=cyc_op, minpoly_v=str(mv), primary=prim, obstruction=obst)
    res['t_series'] = round(tser, 2); res['t_basis'] = round(tbas, 2); res['secs'] = round(time.time() - T0, 2)
    return res

if __name__ == '__main__':
    lo, hi, out = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3]
    done = set()
    if os.path.exists(out):
        for line in open(out):
            try: done.add(json.loads(line)['l'])
            except Exception: pass
    for l in sympy.primerange(lo, hi + 1):
        if l in done: continue
        o = analyze(l)
        with open(out, 'a') as fh: fh.write(json.dumps(o) + '\n')
        flag = '' if (o['thmA'] and o['d_l_zero'] and o['ss0'] and o['okU'] and o['okD']) else '  <<< CHECK FAILURE'
        print(f"l={l} d={o['d']} R={o['R']} det={o['detXi']} kry={o['krylov']} sqfree={o['sqfree']} "
              f"{o['secs']}s{flag}" + (f"  EXC: {o['exception']['obstruction']}" if 'exception' in o else ''), flush=True)
